const updateCategory = `-- name: UpdateCategory :execrows
UPDATE notification_categories
SET name = $1, description = $2, position = $3,
    text_version = text_version + $4::int,
    text_changed_at = CASE WHEN $4::int > 0 THEN now() ELSE text_changed_at END,
    version = version + 1, updated_at = now()
WHERE id = $5 AND version = $6
`

type UpdateCategoryParams struct {
	Name            string
	Description     string
	Position        int32
	VersionBump     int32
	ID              uuid.UUID
	ExpectedVersion int64
}

// Asking again bumps the text version: answers to an older text stop counting.
func (q *Queries) UpdateCategory(ctx context.Context, arg UpdateCategoryParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCategory,
		arg.Name,
		arg.Description,
		arg.Position,
		arg.VersionBump,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateRule = `-- name: UpdateRule :execrows
UPDATE notification_rules
SET name = $1, description = $2, category_id = $3,
    enabled = $4, mandatory = $5, trigger_type = $6,
    trigger_event = $7, definition = $8::text::jsonb, next_run_at = NULL,
    version = version + 1, updated_at = now()
WHERE id = $9 AND version = $10
`

type UpdateRuleParams struct {
	Name            string
	Description     string
	CategoryID      *uuid.UUID
	Enabled         bool
	Mandatory       bool
	TriggerType     string
	TriggerEvent    *string
	Definition      string
	ID              uuid.UUID
	ExpectedVersion int64
}

// A changed definition clears next_run_at so the scheduler computes it afresh.
func (q *Queries) UpdateRule(ctx context.Context, arg UpdateRuleParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateRule,
		arg.Name,
		arg.Description,
		arg.CategoryID,
		arg.Enabled,
		arg.Mandatory,
		arg.TriggerType,
		arg.TriggerEvent,
		arg.Definition,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

